const app=document.getElementById('app');
let page='files',dark=localStorage.getItem('theme')!=='light',calcProject=null,manualThumb=null;
document.body.dataset.theme=dark?'dark':'light';
const api=async(u,o={})=>{const r=await fetch(u,o);const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.detail||'Ошибка');return d};
const money=n=>n==null?'—':new Intl.NumberFormat('ru-RU',{style:'currency',currency:'RUB',maximumFractionDigits:2}).format(n);
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
function shell(){app.innerHTML=`<div class="app"><aside><div class="brand"><span class="cube">◇</span><div><b>3D PRINT</b><small>MANAGER</small></div></div><nav><button class="${page==='files'?'active':''}" onclick="go('files')">▦ <span>Библиотека</span></button><button class="${page==='calc'?'active':''}" onclick="go('calc')">₽ <span>Калькулятор</span></button></nav><div class="sidebottom"><button onclick="toggleTheme()">◐ <span>${dark?'Светлая тема':'Тёмная тема'}</span></button><button class="${page==='settings'?'active':''}" onclick="go('settings')">⚙ <span>Настройки</span></button></div></aside><main><header><div><h1>${page==='files'?'Библиотека':page==='calc'?'Калькулятор':'Настройки'}</h1><p>${page==='files'?'Добавляй каждую модель вручную — без автоматического сканирования папок.':'Локально · без облака'}</p></div><div class="status">● Готово</div></header><div id="content" class="page"></div></main></div>`;if(page==='files')files();if(page==='calc')calculator();if(page==='settings')settings()}
function go(p){page=p;shell()}
function toggleTheme(){dark=!dark;localStorage.setItem('theme',dark?'dark':'light');document.body.dataset.theme=dark?'dark':'light';shell()}
async function files(){const c=document.getElementById('content');c.innerHTML=`<div class="toolbar"><div class="search">⌕ <input id="q" placeholder="Поиск по названию, файлу и тегам..."></div><button onclick="loadFiles()">Обновить</button><button class="primary" onclick="openAddModal()">＋ Добавить модель</button></div><div id="count" class="muted">Загрузка...</div><div id="grid" class="grid"></div>`;document.getElementById('q').oninput=loadFiles;loadFiles()}
let fileTimer;
async function loadFiles(){clearTimeout(fileTimer);fileTimer=setTimeout(async()=>{try{const q=document.getElementById('q')?.value||'';const d=await api('/api/projects?q='+encodeURIComponent(q));const count=document.getElementById('count');const grid=document.getElementById('grid');if(!count||!grid)return;count.textContent='Найдено: '+d.total+' проектов';grid.innerHTML=d.items.length?d.items.map(p=>{const f=p.files[0]||{};const time=f.print_time_seconds?fmtTime(f.print_time_seconds):'Время не указано';return `<div class="card" onclick='openProject(${JSON.stringify(p).replace(/'/g,"&#39;")})'>${p.thumbnail?`<img src="/api/thumbnail/${encodeURIComponent(p.thumbnail)}">`:'<div class="thumb">3D</div>'}<div class="cardbody"><h3>${esc(p.name)}</h3><div class="muted">${esc(f.filename||'Файл не указан')}</div><div class="tags">${p.tags.map(t=>`<span>#${esc(t)}</span>`).join('')}</div><div class="stats">${f.weight_g!=null?esc(f.weight_g)+' г':'Вес не указан'} · ${time}</div></div></div>`}).join(''):'<div class="empty"><h2>Библиотека пока пустая</h2><p>Нажми «＋ Добавить модель», выбери STL/3MF/OBJ/STEP, задай название, вес, время и теги.</p><button class="primary" onclick="openAddModal()">＋ Добавить первую модель</button></div>'}catch(e){const count=document.getElementById('count');if(count)count.textContent=e.message}},250)}
function fmtTime(sec){sec=Number(sec)||0;const h=Math.floor(sec/3600),m=Math.floor((sec%3600)/60);return h?`${h} ч ${m} мин`:`${m} мин`}
function openAddModal(){manualThumb=null;document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="addModal"><div class="modalbox addbox"><button class="close" onclick="closeAddModal()">×</button><h2>Добавить модель</h2><p class="muted">Заполняй данные вручную — они будут сохранены вместе с моделью.</p><form id="addForm"><label class="formlabel">Файл модели <input id="modelFile" type="file" accept=".stl,.3mf,.obj,.step,.stp" required></label><div class="filehint" id="fileHint">STL, 3MF, OBJ, STEP или STP</div><label class="formlabel">Название проекта <input id="projectName" placeholder="Например: Подставка для телефона" required></label><label class="formlabel">Теги <input id="projectTags" placeholder="органайзер, подарок, PLA"></label><div class="twocol"><label class="formlabel">Вес, г <input id="modelWeight" type="number" min="0.01" step="0.01" placeholder="42.5" required></label><label class="formlabel">Материал <input id="modelMaterial" placeholder="PLA"></label></div><div class="timebox"><b>Время печати</b><div class="twocol"><label class="formlabel">Часы <input id="printHours" type="number" min="0" value="0" required></label><label class="formlabel">Минуты <input id="printMinutes" type="number" min="0" max="59" value="0" required></label></div></div><div class="pastebox" id="pasteBox" tabindex="0"><div id="pastePreview">📋 <b>Вставить фото из буфера</b><span>Сделай скриншот → Ctrl+V сюда</span></div></div><label class="formlabel">Или выбрать фото <input id="thumbFile" type="file" accept="image/png,image/jpeg,image/webp"></label><div id="addError"></div><div class="modalactions"><button type="button" onclick="closeAddModal()">Отмена</button><button class="primary" type="submit">Сохранить модель</button></div></form></div></div>`);const box=document.getElementById('pasteBox');box.addEventListener('paste',handlePaste);document.getElementById('modelFile').addEventListener('change',e=>{document.getElementById('fileHint').textContent=e.target.files[0]?.name||'STL, 3MF, OBJ, STEP или STP'});document.getElementById('thumbFile').addEventListener('change',e=>{if(e.target.files[0])setThumb(e.target.files[0])});document.getElementById('addForm').addEventListener('submit',submitManual)}
function closeAddModal(){document.getElementById('addModal')?.remove();manualThumb=null}
async function handlePaste(e){const items=[...(e.clipboardData?.items||[])];const item=items.find(x=>x.type.startsWith('image/'));if(!item)return;const blob=item.getAsFile();if(blob){e.preventDefault();setThumb(blob)}}
function setThumb(file){manualThumb=file;const url=URL.createObjectURL(file);document.getElementById('pastePreview').innerHTML=`<img class="pastepreview" src="${url}"><span>Фото готово. Можно сохранить модель.</span>`}
async function submitManual(e){e.preventDefault();const err=document.getElementById('addError');err.innerHTML='';const file=document.getElementById('modelFile').files[0];const h=Number(document.getElementById('printHours').value||0),m=Number(document.getElementById('printMinutes').value||0);if(!file)return; if(h===0&&m===0){err.innerHTML='<div class="error">Укажи время печати.</div>';return}const fd=new FormData();fd.append('model',file);fd.append('name',document.getElementById('projectName').value.trim());fd.append('tags',document.getElementById('projectTags').value);fd.append('weight_g',document.getElementById('modelWeight').value);fd.append('print_time_seconds',String(h*3600+m*60));fd.append('material',document.getElementById('modelMaterial').value);if(manualThumb)fd.append('thumbnail',manualThumb,'screenshot.png');const btn=e.submitter;btn.disabled=true;btn.textContent='Сохраняю...';try{await api('/api/projects/manual',{method:'POST',body:fd});closeAddModal();await loadFiles()}catch(x){err.innerHTML='<div class="error">'+esc(x.message)+'</div>';btn.disabled=false;btn.textContent='Сохранить модель'}}
function openProject(p){const f=p.files[0]||{};document.getElementById('content').insertAdjacentHTML('beforeend',`<div class="modal"><div class="modalbox"><button class="close" onclick="this.parentNode.parentNode.remove()">×</button><h2>${esc(p.name)}</h2><div class="detailgrid"><div>${p.thumbnail?`<img class="largepreview" src="/api/thumbnail/${encodeURIComponent(p.thumbnail)}">`:'<div class="thumb largepreview">3D</div>'}</div><div><p><b>Файл:</b> ${esc(f.filename||'—')}</p><p><b>Вес:</b> ${f.weight_g??'—'} г</p><p><b>Время:</b> ${f.print_time_seconds?fmtTime(f.print_time_seconds):'—'}</p><p><b>Материал:</b> ${esc(f.material||'—')}</p><p><b>Теги:</b> ${esc(p.tags.join(', ')||'нет')}</p><div class="fileactions"><a class="buttonlike" href="/api/file/${f.id}" target="_blank">Открыть / скачать файл</a><button class="primary" onclick='calcProject=${JSON.stringify(p)};this.parentNode.parentNode.parentNode.parentNode.remove();go("calc")'>Рассчитать стоимость</button></div></div></div></div></div>`)}
async function calculator(){const c=document.getElementById('content');const d=await api('/api/settings');const f=calcProject?.files?.[0]||{};const sec=f.print_time_seconds||3600;c.innerHTML=`<div class="calcpage"><div class="calcform"><h2>Расчёт стоимости</h2>${calcProject?`<div class="selectedmodel"><b>Модель:</b> ${esc(calcProject.name)}<br><span>${esc(f.filename||'')}</span></div>`:''}<label>Клиент<select id="client"><option value="friend">Друг</option><option value="customer" selected>Заказчик</option><option value="ozon">Ozon</option></select></label><label>Материал<select id="mat">${d.materials.filter(x=>x.active).map(x=>`<option ${f.material===x.name?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label>Принтер<select id="printer">${d.printers.filter(x=>x.active).map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></label><label>Вес, г<input id="weight" type="number" min=".01" value="${f.weight_g??10}"></label><div class="twocol"><label>Часы<input id="hours" type="number" min="0" value="${Math.floor(sec/3600)}"></label><label>Минуты<input id="minutes" type="number" min="0" max="59" value="${Math.floor(sec%3600/60)}"></label></div><label>Количество<input id="qty" type="number" min="1" value="1"></label><label>Режим<select id="mode"><option value="hobby">Хобби</option><option value="sale" selected>Продажа</option></select></label><button class="primary big" onclick="doCalc()">Рассчитать</button><div id="err"></div></div><div id="result" class="result"><h2>Результат</h2><div class="muted">Введите параметры и нажмите «Рассчитать».</div></div></div>`}
async function doCalc(){try{document.getElementById('err').innerHTML='';const req={client_type:document.getElementById('client').value,material:document.getElementById('mat').value,printer_id:Number(document.getElementById('printer').value),weight_g:Number(document.getElementById('weight').value),print_time_seconds:Number(document.getElementById('hours').value)*3600+Number(document.getElementById('minutes').value)*60,quantity:Number(document.getElementById('qty').value),mode:document.getElementById('mode').value};const r=await api('/api/calculate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(req)});const rows=[['Материал',r.material_cost],['Электроэнергия',r.electricity_cost],['Ресурс принтера',r.printer_resource_cost],['Обслуживание',r.maintenance_cost],['Расходники',r.consumables_cost],['Работа оператора',r.operator_cost],['Упаковка',r.packaging_cost],['Резерв брака',r.waste_reserve]];if(req.client_type==='ozon')rows.push(['Комиссия Ozon',r.ozon_commission],['Эквайринг',r.acquiring],['Налог',r.tax],['Логистика и фикс. расходы',r.ozon_fixed_and_logistics]);document.getElementById('result').innerHTML=`<h2>Результат</h2>${rows.map(x=>`<div class="resultrow"><span>${x[0]}</span><b>${money(x[1])}</b></div>`).join('')}<hr><div class="resultrow strong"><span>Себестоимость</span><b>${money(r.break_even_cost)}</b></div><div class="resultrow strong"><span>Рекомендуемая цена</span><b>${money(r.recommended_price)}</b></div><div class="resultrow"><span>Цена 1 шт.</span><b>${money(r.price_per_unit)}</b></div><div class="resultrow"><span>Прибыль</span><b>${money(r.profit)}</b></div><div class="resultrow"><span>Маржа</span><b>${r.margin_percent.toFixed(2)} %</b></div>`}catch(e){document.getElementById('err').innerHTML='<div class="error">'+esc(e.message)+'</div>'}}
async function settings(){const d=await api('/api/settings');const val=k=>JSON.parse(d.settings[k]??'0');document.getElementById('content').innerHTML=`<div class="settings"><h2>Настройки</h2><section><h3>Добавление моделей</h3><p class="muted">Автоматический поиск по папкам отключён. Новую модель добавляй через кнопку «＋ Добавить модель» в библиотеке. Так название, теги, вес, время и фото всегда будут именно теми, которые ты указал.</p><button class="primary" onclick="go('files');setTimeout(openAddModal,50)">＋ Добавить модель</button></section><section><h3>Материалы</h3><div class="settinggrid">${d.materials.map(m=>`<label class="mini"><b>${esc(m.name)}</b><input data-mid="${m.id}" type="number" value="${m.spool_price}" onblur="saveMaterial(${m.id},this.value)"><span>${money(m.spool_price/m.spool_weight_g)}/г</span></label>`).join('')}</div></section><section><h3>Цены и расчёты</h3><div class="settinggrid">${[['electricity_price_kwh','Электроэнергия, ₽/кВт⋅ч'],['defect_percent','Брак, %'],['markup_percent','Наценка, %'],['operator_rate','Оператор, ₽/ч'],['prep_minutes','Подготовка, мин'],['packaging_per_unit','Упаковка, ₽/шт'],['ozon_commission_percent','Ozon комиссия, %'],['acquiring_percent','Эквайринг, %'],['tax_percent','Налог, %'],['ozon_logistics','Ozon логистика, ₽'],['ozon_other','Ozon прочие, ₽']].map(x=>`<label class="mini">${x[1]}<input id="s_${x[0]}" type="number" value="${val(x[0])}"></label>`).join('')}</div><button class="primary" onclick="saveSettings()">Сохранить настройки</button><span id="saved" class="saved"></span></section><section><h3>Импорт Excel</h3><div class="row"><input id="excel" type="file" accept=".xlsx"><button onclick="previewExcel()">Предпросмотр</button><button class="primary" onclick="applyExcel()">Применить Excel</button></div><div id="excelmsg" class="muted"></div></section><section><h3>Принтеры</h3>${d.printers.map(p=>`<div class="printer"><b>${esc(p.name)}</b><span>${p.average_power_w} Вт</span><span>${money(p.purchase_price)}</span><span>${p.resource_hours} ч</span></div>`).join('')}</section></div>`}
async function saveMaterial(id,v){await api('/api/settings/materials/'+id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({spool_price:Number(v)})})}
async function saveSettings(){const keys=['electricity_price_kwh','defect_percent','markup_percent','operator_rate','prep_minutes','packaging_per_unit','ozon_commission_percent','acquiring_percent','tax_percent','ozon_logistics','ozon_other'];const settings={};keys.forEach(k=>settings[k]=Number(document.getElementById('s_'+k).value));await api('/api/settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({settings})});document.getElementById('saved').textContent='Сохранено';setTimeout(()=>document.getElementById('saved').textContent='',2000)}
async function previewExcel(){const f=document.getElementById('excel').files[0];if(!f)return;const fd=new FormData();fd.append('file',f);const r=await fetch('/api/settings/excel/import',{method:'POST',body:fd});const x=await r.json();document.getElementById('excelmsg').textContent=`Предпросмотр: ${x.materials.length} материалов, ${x.printers.length} принтеров, листы: ${x.sheets.join(', ')}`}
async function applyExcel(){const f=document.getElementById('excel').files[0];if(!f)return document.getElementById('excelmsg').textContent='Выберите Excel';const fd=new FormData();fd.append('file',f);const r=await fetch('/api/settings/excel/apply',{method:'POST',body:fd});if(!r.ok)return document.getElementById('excelmsg').textContent='Ошибка импорта';document.getElementById('excelmsg').textContent='Excel применён';setTimeout(settings,300)}
shell();
